SourceCode.Declaration:
/// <summary>
/// Stores everything from GUPPriceComponentCode and direct-related tables (i.e. priority of all combinations under them).
/// </summary>
internal class GUPPriceEngineAttributeGroupPriorityCache
{
    Map priceComponentByUniqueKey = null;

    Map priceComponentCodeMapByEnum = null;

}

Method.Source:
private void doRefresh()
{
    // Key = GUPPriceComponentCodePriceAttributeGroupCombination.parmUniqueKey().
    // Value = Priority (Int64).
    priceComponentByUniqueKey = new Map(Types::String, Types::Int64);

    // Key = PriceComponent (Enum), Value = GUPPriceComponentCode (int64).
    // Only valid for GUPPriceComponent with unique component code (e.g. TradeAgreement).
    priceComponentCodeMapByEnum = new Map(Types::Enum, Types::Int64);

    // Load all trade agreements' priorities, and margin codes' priorities existed in setup.
    GUPPriceMarginComponentSetup marginCodeSetup;
    GUPPriceComponentCode gupPriceComponentCode;
    GUPPriceComponentCodePriceAttributeGroupCombination gupPriceComponentCodePriceAttributeGroupCombination;
    while select * from gupPriceComponentCode
        join gupPriceComponentCodePriceAttributeGroupCombination
        where gupPriceComponentCode.RecId == gupPriceComponentCodePriceAttributeGroupCombination.PriceComponentCode
        outer join RecId from marginCodeSetup
        where gupPriceComponentCode.RecId == marginCodeSetup.PriceComponentCode &&
            ((gupPriceComponentCode.PriceComponent == GUPPriceComponent::SalesTradeAgreement) ||
            (marginCodeSetup.RecId != 0))

    {
        GUPPriceComponent priceComponent = gupPriceComponentCode.PriceComponent;
        priceComponentByUniqueKey.add(gupPriceComponentCodePriceAttributeGroupCombination.parmUniqueKey(), 
            gupPriceComponentCodePriceAttributeGroupCombination.Priority);

        priceComponentCodeMapByEnum.add(gupPriceComponentCode.PriceComponent, gupPriceComponentCodePriceAttributeGroupCombination.PriceComponentCode);
    }

}

public int64 getPriority(int64 _headerAttributeGroup,
    int64 _lineAttributeGroup,  
    int64 _priceComponentCode)
{
    str key = GUPPriceComponentCodePriceAttributeGroupCombination::generateUniqueKey(_priceComponentCode, _headerAttributeGroup, _lineAttributeGroup);
    return priceComponentByUniqueKey.lookup(key);
}

/// <summary>
/// Get priority from cache by attribute group ids and component code.
/// Notice: attibute group id can be 0, indicates ALL headers / lines are allowed with this rule.
/// </summary>
/// <param name = "_line">An GUPPriceEngineAbstractLine.</param>
/// <param name = "_priceComponentCode">Price Component code.</param>
/// <returns>Priority from selected component code type.</returns>
public int64 getLinePriority (GUPPriceEngineAbstractLine _line,
    int64 _priceComponentCode)
{
    int64 headerGroupId = (_line.parmHeaderAttribute()) ? _line.parmHeaderAttribute().parmPricingAttributeGroup().RecId : 0;
    int64 lineGroupId = (_line.parmLineAttribute()) ? _line.parmLineAttribute().parmPricingAttributeGroup().RecId : 0;

    return this.getPriority(headerGroupId, lineGroupId, _priceComponentCode);
}
